import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback

flowFile = session.get()
if (!flowFile) return

def data

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def text = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    data = new JsonSlurper().parseText(text)

    // data 가공
    data.each { it.processed = true }

    def json = JsonOutput.toJson(data)
    outputStream.write(json.getBytes("UTF-8"))
} as StreamCallback)

// data를 JSON 문자열로 변환하여 attribute에 저장
flowFile = session.putAttribute(flowFile, "flowfile.a.data", JsonOutput.toJson(data))

session.transfer(flowFile, REL_SUCCESS)

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
def flowFile = session.get()
if (flowFile == null) return

try {
    ObjectMapper mapper = new ObjectMapper()

    // 1. 원본 데이터 가져오기
    String originalJsonA = flowFile.getAttribute("flowfile.a.data")
	String originalJsonB = flowFile.getAttribute("flowfile.b.data")

    // TypeReference 대신 List.class 사용
    List<Map<String, Object>> originListMap = mapper.readValue(originalJsonA, List.class)

    log.info("원본 데이터: " + originListMap)

    // 2. 매핑 코드 읽기
    String mappingcode = ""
    session.read(flowFile) { inputStream ->
        mappingcode = inputStream.getText('UTF-8')
    }

    // TypeReference 대신 List.class 사용
    List<Map<String, Object>> codeListMap = mapper.readValue(originalJsonB, List.class)

    log.info("매핑 코드: " + codeListMap)

	String dzCoCd = codeListMap.find {
		it.columnId == "DZ_CO_CD" && it.ediCd1 != ""
	}?.ediCd1

	String dzAcctCd = codeListMap.find {
		it.columnId == "DZ_ACCT_CD" && it.ediCd1 != ""
	}?.ediCd1

	String dzTrCd = codeListMap.find {
		it.columnId == "DZ_TR_CD" && it.ediCd1 != ""
	}?.ediCd1

    if (!dzCoCd) throw new Exception("not found dzCdCd 회사코드를 찾을 수 없습니다." + originListMap + codeListMap)
    if (!dzAcctCd) throw new Exception("not found dzAcctCd 계정과목코드를 찾을 수 없습니다.")
    if (!dzTrCd) throw new Exception("not found dzTrCd 거래처코드를 찾을 수 없습니다.")

    log.info("매핑 값: CO_CD=${dzCoCd}, ACCT_CD=${dzAcctCd}, TR_CD=${dzTrCd}")

    // 4. 원본 데이터에 매핑 적용
    List<Map<String, Object>> sendDouzoneMap = []

    originListMap.each { origin ->
        origin.coCd = dzCoCd
        origin.acctCd = dzAcctCd
        origin.trCd = dzTrCd
        sendDouzoneMap.add(origin)
    }

    // 5. 결과 쓰기
    flowFile = session.write(flowFile) { inputStream, outputStream ->
        String result = mapper.writerWithDefaultPrettyPrinter()
                             .writeValueAsString(sendDouzoneMap)
        outputStream.write(result.getBytes('UTF-8'))
    }
    log.info("douzone code mapping success !!")
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("douzone code mapping fail !! : " + e.message, e)
    flowFile = session.putAttribute(flowFile, "error.message", e.message)
    session.transfer(flowFile, REL_FAILURE)
}

